package com.bookstore.controller; import com.bookstore.entity.OrderStatus; import com.bookstore.service.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.*; @Controller @RequestMapping("/orders") public class OrderController{private final OrderService orders;private final CustomerService customers;private final BookService books;public OrderController(OrderService o,CustomerService c,BookService b){orders=o;customers=c;books=b;}@GetMapping String list(Model m){m.addAttribute("orders",orders.findAll());return "orders/list";}@GetMapping("/{id}")String view(@PathVariable Long id,Model m){m.addAttribute("order",orders.findById(id));m.addAttribute("statuses",OrderStatus.values());return "orders/view";}@GetMapping("/new")String form(Model m){m.addAttribute("customers",customers.findAll());m.addAttribute("books",books.findAll());return "orders/form";}@PostMapping("/create")String create(@RequestParam Long customerId,@RequestParam("bookIds")List<Long> ids,@RequestParam("quantities")List<Integer> qtys){return "redirect:/orders/"+orders.create(customerId,ids,qtys).getId();}@PostMapping("/{id}/status")String status(@PathVariable Long id,@RequestParam OrderStatus status){orders.updateStatus(id,status);return "redirect:/orders/"+id;}}